package main

import (
    "encoding/json"
    "os"
)

func main() {
    var sysin map[string]interface{}
    json.NewDecoder(os.Stdin).Decode(&sysin)
    json.NewEncoder(os.Stdout).Encode(sysin["n"])
}

package main

import (
    "encoding/json"
    "os"
)

func main() {
    var sysin map[string]float64
    json.NewDecoder(os.Stdin).Decode(&sysin)
    result := sysin["a"] + sysin["b"]
    json.NewEncoder(os.Stdout).Encode(result)
}
